from typing import Any

from worker import PaymentWorker


def run_with_retry_scenario(worker: PaymentWorker, operation_id: str) -> list[dict[str, Any]]:
    first = {
        "operation_id": operation_id,
        "attempt_id": f"{operation_id}-a1",
        "customer_id": "cust-1",
        "amount_cents": 1999,
        "currency": "USD",
        "metadata": {"network_status": "timeout", "attempt_index": 0},
    }
    second = {
        "operation_id": operation_id,
        "attempt_id": f"{operation_id}-a2",
        "customer_id": "cust-1",
        "amount_cents": 1999,
        "currency": "USD",
        "metadata": {"network_status": "ok", "attempt_index": 1},
    }
    return [worker.process(first), worker.process(second)]


def count_ok(results: list[dict[str, Any]]) -> int:
    count = 0
    for result in results:
        if bool(result.get("ok", False)):
            count += 1
    return count


def collect_gateway_ids(results: list[dict[str, Any]]) -> list[str]:
    ids: list[str] = []
    for result in results:
        gid = str(result.get("gateway_charge_id", "")).strip()
        if gid:
            ids.append(gid)
    return ids


def summarize(worker: PaymentWorker, operation_id: str) -> dict[str, Any]:
    return {
        "successful_charge_records": worker.successful_charges_for_operation(operation_id),
        "gateway_charge_ids": worker.gateway_charges_for_operation(operation_id),
        "diagnostics": worker.diagnostics(),
    }


def run_many(worker: PaymentWorker, operations: list[str]) -> dict[str, Any]:
    report: dict[str, Any] = {}
    for operation_id in operations:
        results = run_with_retry_scenario(worker, operation_id)
        report[operation_id] = {
            "ok_count": count_ok(results),
            "gateway_ids": collect_gateway_ids(results),
            "summary": summarize(worker, operation_id),
        }
    return report

