from dataclasses import dataclass
from threading import Lock
from typing import Any


@dataclass(frozen=True)
class EventLogEntry:
    event_type: str
    operation_id: str
    attempt_id: str
    payload: dict[str, Any]


class EventLog:
    def __init__(self) -> None:
        self._lock = Lock()
        self._entries: list[EventLogEntry] = []

    def add(self, event_type: str, operation_id: str, attempt_id: str, payload: dict[str, Any]) -> None:
        entry = EventLogEntry(
            event_type=event_type.strip() or "unknown",
            operation_id=operation_id.strip(),
            attempt_id=attempt_id.strip(),
            payload=dict(payload),
        )
        with self._lock:
            self._entries.append(entry)

    def list_all(self) -> list[EventLogEntry]:
        with self._lock:
            return list(self._entries)

    def for_operation(self, operation_id: str) -> list[EventLogEntry]:
        target = operation_id.strip()
        if not target:
            return []
        with self._lock:
            return [entry for entry in self._entries if entry.operation_id == target]

    def count(self) -> int:
        with self._lock:
            return len(self._entries)

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def summary(self) -> dict[str, int]:
        with self._lock:
            counters: dict[str, int] = {}
            for entry in self._entries:
                counters[entry.event_type] = counters.get(entry.event_type, 0) + 1
        return counters

    def latest_for_operation(self, operation_id: str) -> EventLogEntry | None:
        items = self.for_operation(operation_id)
        if not items:
            return None
        return items[-1]

    def latest_type_for_operation(self, operation_id: str) -> str:
        latest = self.latest_for_operation(operation_id)
        if latest is None:
            return ""
        return latest.event_type

