from __future__ import annotations

from threading import Lock
from typing import Any


class IdempotencyCache:
    def __init__(self) -> None:
        self._lock = Lock()
        self._values: dict[str, dict[str, Any]] = {}

    def get(self, key: str) -> dict[str, Any] | None:
        normalized = key.strip()
        if not normalized:
            return None
        with self._lock:
            value = self._values.get(normalized)
            return dict(value) if value is not None else None

    def set(self, key: str, value: dict[str, Any]) -> None:
        normalized = key.strip()
        if not normalized:
            raise ValueError("idempotency key is required")
        with self._lock:
            self._values[normalized] = dict(value)

    def has(self, key: str) -> bool:
        normalized = key.strip()
        if not normalized:
            return False
        with self._lock:
            return normalized in self._values

    def delete(self, key: str) -> bool:
        normalized = key.strip()
        if not normalized:
            return False
        with self._lock:
            if normalized in self._values:
                del self._values[normalized]
                return True
            return False

    def clear(self) -> None:
        with self._lock:
            self._values.clear()

    def count(self) -> int:
        with self._lock:
            return len(self._values)

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(value) for key, value in self._values.items()}

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._values.keys())

    def upsert_reason(self, key: str, reason: str) -> None:
        normalized = key.strip()
        if not normalized:
            return
        with self._lock:
            current = dict(self._values.get(normalized, {}))
            current["reason"] = reason
            self._values[normalized] = current

