from threading import Lock

from contracts import ChargeRequest, GatewayResponse


class FakePaymentGateway:
    def __init__(self) -> None:
        self._lock = Lock()
        self._charge_count = 0
        self._by_operation: dict[str, list[str]] = {}

    def charge(self, request: ChargeRequest) -> GatewayResponse:
        timeout_mode = str(request.metadata.get("network_status", "")).strip().lower()
        should_timeout = timeout_mode == "timeout"

        with self._lock:
            self._charge_count += 1
            gateway_charge_id = f"ch_{self._charge_count:05d}"
            operation_list = self._by_operation.setdefault(request.operation_id, [])
            operation_list.append(gateway_charge_id)

        if should_timeout:
            return GatewayResponse(
                ok=False,
                gateway_charge_id=gateway_charge_id,
                reason="network_timeout_after_capture",
                was_timeout=True,
            )

        return GatewayResponse(
            ok=True,
            gateway_charge_id=gateway_charge_id,
            reason="captured",
            was_timeout=False,
        )

    def charge_count(self) -> int:
        with self._lock:
            return self._charge_count

    def charges_for_operation(self, operation_id: str) -> list[str]:
        key = operation_id.strip()
        if not key:
            return []
        with self._lock:
            return list(self._by_operation.get(key, []))

    def reset(self) -> None:
        with self._lock:
            self._charge_count = 0
            self._by_operation.clear()

    def unique_operation_count(self) -> int:
        with self._lock:
            return len(self._by_operation)

    def duplicate_operation_ids(self) -> list[str]:
        with self._lock:
            return sorted(
                op_id
                for op_id, charge_ids in self._by_operation.items()
                if len(charge_ids) > 1
            )

