@dataclass(frozen=True)
class AttemptRecord:
    operation_id: str
    attempt_id: str
    status: str
    gateway_charge_id: str
    reason: str


class ChargeRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._attempts: list[AttemptRecord] = []
        self._status_by_operation: dict[str, str] = {}
        self._latest_by_operation: dict[str, AttemptRecord] = {}

    def save_attempt(
        self,
        *,
        operation_id: str,
        attempt_id: str,
        status: str,
        gateway_charge_id: str,
        reason: str,
    ) -> AttemptRecord:
        record = AttemptRecord(
            operation_id=operation_id.strip(),
            attempt_id=attempt_id.strip(),
            status=status.strip(),
            gateway_charge_id=gateway_charge_id.strip(),
            reason=reason.strip(),
        )
        with self._lock:
            self._attempts.append(record)
            self._status_by_operation[record.operation_id] = record.status
            self._latest_by_operation[record.operation_id] = record
        return record

    def latest_for_operation(self, operation_id: str) -> AttemptRecord | None:
        key = operation_id.strip()
        if not key:
            return None
        with self._lock:
            return self._latest_by_operation.get(key)

    def status_for_operation(self, operation_id: str) -> str | None:
        key = operation_id.strip()
        if not key:
            return None
        with self._lock:
            return self._status_by_operation.get(key)

    def attempts_for_operation(self, operation_id: str) -> list[AttemptRecord]:
        key = operation_id.strip()
        if not key:
            return []
        with self._lock:
            return [item for item in self._attempts if item.operation_id == key]

    def has_successful_charge(self, operation_id: str) -> bool:
        for attempt in self.attempts_for_operation(operation_id):
            if attempt.status == "success":
                return True
        return False

    def count(self) -> int:
        with self._lock:
            return len(self._attempts)

    def clear(self) -> None:
        with self._lock:
            self._attempts.clear()
            self._status_by_operation.clear()
            self._latest_by_operation.clear()

    def export(self) -> dict[str, Any]:
        with self._lock:
            attempts = [
                {
                    "operation_id": item.operation_id,
                    "attempt_id": item.attempt_id,
                    "status": item.status,
                    "gateway_charge_id": item.gateway_charge_id,
                    "reason": item.reason,
                }
                for item in self._attempts
            ]
            latest = {
                key: {
                    "attempt_id": value.attempt_id,
                    "status": value.status,
                    "gateway_charge_id": value.gateway_charge_id,
                }
                for key, value in self._latest_by_operation.items()
            }
        return {"attempts": attempts, "latest_by_operation": latest}

    def successful_charge_count(self, operation_id: str) -> int:
        count = 0
        for attempt in self.attempts_for_operation(operation_id):
            if attempt.status == "success":
                count += 1
        return count

    def latest_success_gateway_id(self, operation_id: str) -> str:
        attempts = self.attempts_for_operation(operation_id)
        for attempt in reversed(attempts):
            if attempt.status == "success":
                return attempt.gateway_charge_id
        return ""

    def operation_seen(self, operation_id: str) -> bool:
        key = operation_id.strip()
        if not key:
            return False
        with self._lock:
            return key in self._status_by_operation

