            self._status_by_operation.clear()
            self._latest_by_operation.clear()

    def export(self) -> dict[str, Any]:
        with self._lock:
            attempts = [
                {
                    "operation_id": item.operation_id,
                    "attempt_id": item.attempt_id,
                    "status": item.status,
                    "gateway_charge_id": item.gateway_charge_id,
                    "reason": item.reason,
                }
                for item in self._attempts
            ]
            latest = {
                key: {
                    "attempt_id": value.attempt_id,
                    "status": value.status,
                    "gateway_charge_id": value.gateway_charge_id,
                }
                for key, value in self._latest_by_operation.items()
            }
        return {"attempts": attempts, "latest_by_operation": latest}

    def successful_charge_count(self, operation_id: str) -> int:
        count = 0
        for attempt in self.attempts_for_operation(operation_id):
            if attempt.status == "success":
                count += 1
        return count

    def latest_success_gateway_id(self, operation_id: str) -> str:
        attempts = self.attempts_for_operation(operation_id)
        for attempt in reversed(attempts):
            if attempt.status == "success":
                return attempt.gateway_charge_id
        return ""

    def operation_seen(self, operation_id: str) -> bool:
        key = operation_id.strip()
        if not key:
            return False
        with self._lock:
            return key in self._status_by_operation

